//! Task model and state machine (MT-001, [todo.md](../../todo.md) "task assignment and acknowledgment channel").
//!
//! Pure logic layer, no IO: the task entity (`id` as idempotency key), a linear state machine
//! `assigned → acked → running → done | failed`, and the audit operation names transitions produce.
//! The dispatch channel (server → agent delivery, ack / heartbeat / exit code receipts,
//! idempotent redelivery after disconnects) is MT-002 execution-layer wiring, not here.
//!
//! Design notes:
//! - `id` is the **idempotency key**: generated by the server at dispatch time, resent
//!   unchanged on redelivery, deduplicated by id on the agent (F-2030 traffic re-report);
//! - the state machine is strictly linear: out-of-order / post-terminal events are always
//!   rejected with [TaskError::IllegalTransition] rather than silently swallowed — an
//!   out-of-order receipt is exactly the anomaly that must surface;
//! - `retry_limit` is just data: whether to redispatch is the dispatcher's call (MT-005
//!   timeout reclamation / retry cap), the state machine has no built-in retry loop;
//! - audit follows the repo's "audit operation name" convention (`operation() -> &'static str`),
//!   each transition returning an operation name usable for logs / audit events.

use crate::entities::DeviceId;

/// Task identifier (server-generated, idempotency key; redelivery reuses the same value).
#[derive(
    Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord, serde::Serialize, serde::Deserialize,
)]
pub struct TaskId(pub String);

impl std::fmt::Display for TaskId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

/// Task payload: a single command to run on the target node.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct TaskPayload {
    /// The command to execute.
    pub cmd: String,
    /// Working directory; `None` uses the agent default.
    pub workdir: Option<String>,
    /// Timeout in seconds; `None` uses the agent default.
    pub timeout_secs: Option<u64>,
    /// Label routing requirements (MT-005): every `(key, value)` pair must match the target
    /// node's labels before dispatch; the server uses them for selection/validation while the
    /// agent only executes. `#[serde(default)]` tolerates older servers: no field = no constraint.
    #[serde(default)]
    pub required_labels: std::collections::BTreeMap<String, String>,
}

/// Task state (linear state machine `assigned → acked → running → done | failed`).
///
/// serde uses lowercase variant names, matching the dispatch contract of [TaskState::as_str].
#[derive(Debug, Clone, Copy, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum TaskState {
    /// Assigned: dispatched by the server, not yet confirmed by the agent.
    Assigned,
    /// Agent has confirmed receipt (ack).
    Acked,
    /// Currently running on the target node.
    Running,
    /// Finished successfully (terminal).
    Done,
    /// Finished with failure (terminal).
    Failed,
}

impl TaskState {
    /// Status reporting contract fields (`assigned` / `acked` / `running` / `done` /
    /// `failed`), shared by the dispatch protocol and console display.
    pub fn as_str(self) -> &'static str {
        match self {
            TaskState::Assigned => "assigned",
            TaskState::Acked => "acked",
            TaskState::Running => "running",
            TaskState::Done => "done",
            TaskState::Failed => "failed",
        }
    }

    /// State machine transition (pure function): only legal forward transitions are
    /// accepted; out-of-order / post-terminal events always yield [TaskError::IllegalTransition].
    pub fn transition(self, event: TaskEvent) -> Result<(TaskState, TaskAction), TaskError> {
        match (self, event) {
            (TaskState::Assigned, TaskEvent::Ack) => Ok((TaskState::Acked, TaskAction::Acked)),
            (TaskState::Acked, TaskEvent::Start) => Ok((TaskState::Running, TaskAction::Started)),
            (TaskState::Running, TaskEvent::Complete(TaskOutcome::Success)) => {
                Ok((TaskState::Done, TaskAction::Succeeded))
            }
            (TaskState::Running, TaskEvent::Complete(TaskOutcome::Failure)) => {
                Ok((TaskState::Failed, TaskAction::Failed))
            }
            (from, event) => Err(TaskError::IllegalTransition { from, event }),
        }
    }
}

/// State machine input events (milestones reported by the agent).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaskEvent {
    /// Agent confirmed receipt of the task (ack).
    Ack,
    /// Agent started executing.
    Start,
    /// Execution finished, with the outcome attached.
    Complete(TaskOutcome),
}

/// The outcome of one execution.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaskOutcome {
    /// Success (exit code 0).
    Success,
    /// Failure (non-zero exit code / timeout / failed to start).
    Failure,
}

/// Actions produced by state transitions: the execution layer records audit events / logs from them.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaskAction {
    /// The task was acknowledged by the agent.
    Acked,
    /// The task started executing.
    Started,
    /// The task executed successfully.
    Succeeded,
    /// The task execution failed.
    Failed,
}

impl TaskAction {
    /// Audit operation name (repo audit convention: lowercase hyphenated phrase, no message drift).
    pub fn operation(self) -> &'static str {
        match self {
            TaskAction::Acked => "task ack",
            TaskAction::Started => "task start",
            TaskAction::Succeeded => "task succeed",
            TaskAction::Failed => "task fail",
        }
    }
}

/// State machine errors.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum TaskError {
    /// Illegal transition: an out-of-order or post-terminal event.
    #[error("illegal task transition: {from:?} via {event:?}")]
    IllegalTransition {
        /// The state when the event arrived.
        from: TaskState,
        /// The rejected event.
        event: TaskEvent,
    },
}

/// A task (MT-001 entity).
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct Task {
    /// Idempotency key; redelivery after a disconnect resends the same value.
    pub id: TaskId,
    /// Target node.
    pub target_node: DeviceId,
    /// Payload to execute.
    pub payload: TaskPayload,
    /// Current state.
    pub state: TaskState,
    /// Retry limit (input to the dispatcher's redispatch decision; no built-in retries).
    pub retry_limit: u32,
    /// Result reference (exit code + storage key of the log tail, etc.); `None` until done.
    pub result_ref: Option<String>,
}

impl Task {
    /// Creates a new task (initial state [TaskState::Assigned], no result reference).
    pub fn new(id: TaskId, target_node: DeviceId, payload: TaskPayload, retry_limit: u32) -> Self {
        Task {
            id,
            target_node,
            payload,
            state: TaskState::Assigned,
            retry_limit,
            result_ref: None,
        }
    }

    /// Applies one state machine event; on success advances `state` and returns the transition action (for audit).
    pub fn apply(&mut self, event: TaskEvent) -> Result<TaskAction, TaskError> {
        let (next, action) = self.state.transition(event)?;
        self.state = next;
        Ok(action)
    }

    /// Records the execution result reference (written by the execution layer on completion, e.g. the result storage key).
    pub fn record_result(&mut self, result_ref: impl Into<String>) {
        self.result_ref = Some(result_ref.into());
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn payload() -> TaskPayload {
        TaskPayload {
            cmd: "/usr/bin/true".into(),
            workdir: Some("/tmp".into()),
            timeout_secs: Some(30),
            required_labels: Default::default(),
        }
    }

    fn task() -> Task {
        Task::new(
            TaskId("018f1e2a-9b4c-7d3e-a1b2-3c4d5e6f7a8b".into()),
            DeviceId("dev-1".into()),
            payload(),
            3,
        )
    }

    #[test]
    fn new_task_starts_assigned_with_no_result() {
        let task = task();
        assert_eq!(task.state, TaskState::Assigned);
        assert_eq!(task.result_ref, None);
        assert_eq!(task.retry_limit, 3);
        assert_eq!(task.state.as_str(), "assigned");
    }

    #[test]
    fn success_lifecycle_walks_the_full_chain() {
        let mut task = task();
        assert_eq!(task.apply(TaskEvent::Ack), Ok(TaskAction::Acked));
        assert_eq!(task.state, TaskState::Acked);
        assert_eq!(task.apply(TaskEvent::Start), Ok(TaskAction::Started));
        assert_eq!(task.state, TaskState::Running);
        assert_eq!(
            task.apply(TaskEvent::Complete(TaskOutcome::Success)),
            Ok(TaskAction::Succeeded)
        );
        assert_eq!(task.state, TaskState::Done);
        assert_eq!(task.state.as_str(), "done");
    }

    #[test]
    fn failure_lifecycle_ends_in_failed() {
        let mut task = task();
        task.apply(TaskEvent::Ack).unwrap();
        task.apply(TaskEvent::Start).unwrap();
        assert_eq!(
            task.apply(TaskEvent::Complete(TaskOutcome::Failure)),
            Ok(TaskAction::Failed)
        );
        assert_eq!(task.state, TaskState::Failed);
        assert_eq!(task.state.as_str(), "failed");
    }

    #[test]
    fn terminal_states_reject_every_event() {
        for terminal in [TaskState::Done, TaskState::Failed] {
            for event in [
                TaskEvent::Ack,
                TaskEvent::Start,
                TaskEvent::Complete(TaskOutcome::Success),
                TaskEvent::Complete(TaskOutcome::Failure),
            ] {
                assert_eq!(
                    terminal.transition(event),
                    Err(TaskError::IllegalTransition {
                        from: terminal,
                        event
                    }),
                    "terminal {terminal:?} must reject {event:?}"
                );
            }
        }
    }

    #[test]
    fn out_of_order_events_are_rejected() {
        // Assigned only accepts Ack: Start / Complete are both out of order.
        for event in [TaskEvent::Start, TaskEvent::Complete(TaskOutcome::Success)] {
            assert_eq!(
                TaskState::Assigned.transition(event),
                Err(TaskError::IllegalTransition {
                    from: TaskState::Assigned,
                    event
                })
            );
        }
        // Acked only accepts Start: Ack (duplicate confirmation) / Complete are both out of order.
        for event in [TaskEvent::Ack, TaskEvent::Complete(TaskOutcome::Failure)] {
            assert_eq!(
                TaskState::Acked.transition(event),
                Err(TaskError::IllegalTransition {
                    from: TaskState::Acked,
                    event
                })
            );
        }
        // Running rejects Ack / Start (duplicate receipts must surface, not be silently swallowed).
        for event in [TaskEvent::Ack, TaskEvent::Start] {
            assert_eq!(
                TaskState::Running.transition(event),
                Err(TaskError::IllegalTransition {
                    from: TaskState::Running,
                    event
                })
            );
        }
    }

    #[test]
    fn apply_leaves_state_untouched_on_illegal_event() {
        let mut task = task();
        task.apply(TaskEvent::Ack).unwrap();
        // State does not drift after an out-of-order event (Complete while Acked) is rejected.
        assert!(task
            .apply(TaskEvent::Complete(TaskOutcome::Success))
            .is_err());
        assert_eq!(task.state, TaskState::Acked);
    }

    #[test]
    fn audit_operation_names_are_stable() {
        assert_eq!(TaskAction::Acked.operation(), "task ack");
        assert_eq!(TaskAction::Started.operation(), "task start");
        assert_eq!(TaskAction::Succeeded.operation(), "task succeed");
        assert_eq!(TaskAction::Failed.operation(), "task fail");
    }

    #[test]
    fn record_result_fills_result_ref() {
        let mut task = task();
        task.apply(TaskEvent::Ack).unwrap();
        task.apply(TaskEvent::Start).unwrap();
        task.apply(TaskEvent::Complete(TaskOutcome::Success))
            .unwrap();
        task.record_result("results/018f1e2a.json");
        assert_eq!(task.result_ref.as_deref(), Some("results/018f1e2a.json"));
    }

    #[test]
    fn task_serializes_for_dispatch_round_trip() {
        let task = task();
        let json = serde_json::to_string(&task).unwrap();
        // Dispatch contract fields all present: idempotency key, target node, state, retry limit.
        assert!(json.contains("\"assigned\""));
        assert!(json.contains("\"018f1e2a-9b4c-7d3e-a1b2-3c4d5e6f7a8b\""));
        let back: Task = serde_json::from_str(&json).unwrap();
        assert_eq!(back, task);
    }
}
